CREATE TABLE IF NOT EXISTS `services` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinic_id` BIGINT UNSIGNED DEFAULT 1,
  `slug` VARCHAR(191) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `category` VARCHAR(120) DEFAULT NULL,
  `badge` VARCHAR(100) DEFAULT NULL,
  `icon` VARCHAR(100) DEFAULT 'medical_services',
  `feature_image` VARCHAR(500) DEFAULT NULL,
  `starting_price` VARCHAR(120) DEFAULT NULL,
  `duration` VARCHAR(80) DEFAULT NULL,
  `description` TEXT DEFAULT NULL,
  `details_json` LONGTEXT DEFAULT NULL,
  `display_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `services_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (1, 1, 'routine-examinations', 'Routine Dental Examinations', 'General Dentistry', 'Preventive', 'dentistry', '/dental-saas/images/hero-patient.jpg', 'NHS Band 1 (£26.80) / Private £45.00', '30 mins', '', '{\"id\":1,\"slug\":\"routine-examinations\",\"title\":\"Routine Dental Examinations\",\"category\":\"General Dentistry\",\"badge\":\"Preventive\",\"summary\":\"Comprehensive soft tissue, periodontal, and tooth screenings with digital X-rays to preserve oral wellness.\",\"content\":\"Our comprehensive dental examination evaluates your overall oral health, identifying any early signs of decay, gum disease, or oral pathology.\\r\\n\\r\\nDuring your appointment, our dental surgeon performs digital low-radiation radiography, periodontal probing, and an oral cancer screening. We then discuss personalized preventive recommendations tailored to your oral health goals.\",\"icon\":\"dentistry\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"NHS Band 1 (£26.80) / Private £45.00\",\"duration\":\"30 mins\",\"cdt_code\":\"D0120\",\"display_order\":1,\"is_active\":true,\"created_at\":\"2026-11-20 09:00:00\",\"updated_at\":\"2026-11-25 11:02:28\",\"eyebrow\":\"GENERAL DENTISTRY • ACOCKS GREEN SURGERY\",\"included_items\":[{\"icon\":\"clinical_notes\",\"title\":\"Comprehensive Clinical Assessment\",\"desc\":\"Thorough diagnostic evaluation tailored to Routine Dental Examinations, checking tooth integrity, gum health, and bite alignment.\",\"is_active\":true},{\"icon\":\"radiology\",\"title\":\"Low-Dose Digital Diagnostics\",\"desc\":\"High-definition digital radiography and chairside visual explanation so you understand every step clearly.\",\"is_active\":true},{\"icon\":\"verified_user\",\"title\":\"Transparent NHS & Private Plan\",\"desc\":\"Clear written treatment plan with exact NHS bandings or private fee breakdowns before any procedure begins.\",\"is_active\":true}],\"journey_steps\":[{\"step\":\"01\",\"title\":\"Warm Welcome & Consultation\",\"desc\":\"Discuss your goals, symptoms, or dental anxiety with our friendly Birmingham clinical team.\",\"is_active\":true},{\"step\":\"02\",\"title\":\"Gentle Clinical Examination\",\"desc\":\"Digital imaging and thorough assessment using modern, minimally invasive techniques.\",\"is_active\":true},{\"step\":\"03\",\"title\":\"Tailored Treatment Delivery\",\"desc\":\"Unhurried Routine Dental Examinations performed with your comfort and long-term oral health as top priority.\",\"is_active\":true},{\"step\":\"04\",\"title\":\"Aftercare & Recall Support\",\"desc\":\"Clear home-care advice, transparent follow-up, and preventive recall scheduling.\",\"is_active\":true}],\"pricing_options\":[{\"title\":\"NHS Care Pathway\",\"badge\":\"Standard NHS Banding\",\"price\":\"NHS Band 1–3\",\"features\":[\"Regulated NHS clinical standards\",\"Full diagnostic & treatment plan\",\"Transparent NHS banding fees\"],\"is_featured\":false,\"is_active\":true},{\"title\":\"Routine Dental Examinations (Private)\",\"badge\":\"Most Popular\",\"price\":\"NHS Band 1 (£26.80) / Private £45.00\",\"features\":[\"Extended unhurried appointment time\",\"Premium aesthetic materials\",\"Flexible evening & weekend triage\"],\"is_featured\":true,\"is_active\":true},{\"title\":\"Complete Care + Hygiene\",\"badge\":\"Preventive Bundle\",\"price\":\"Custom Plan\",\"features\":[\"Includes Airflow stain removal\",\"0% APR finance options available\",\"Priority recall reminders\"],\"is_featured\":false,\"is_active\":true}],\"faqs\":[{\"question\":\"Is Routine Dental Examinations painful?\",\"answer\":\"Our clinicians specialize in gentle, unhurried care for nervous patients, using effective numbing and calm pacing to keep you completely comfortable.\",\"is_active\":true},{\"question\":\"How long does Routine Dental Examinations take?\",\"answer\":\"Typical appointments last 30 mins, depending on your individual clinical requirements.\",\"is_active\":true},{\"question\":\"Are both NHS and private options available?\",\"answer\":\"Yes. We clearly explain both NHS and private pathways upfront so you can choose the option that best suits your needs.\",\"is_active\":true}],\"section_flags\":{\"show_included\":true,\"show_journey\":true,\"show_pricing\":true,\"show_faqs\":true}}', 1, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (2, 1, 'dental-hygiene-airflow', 'Dental Hygiene & Airflow Polish', 'Hygiene', 'Airflow Polish', 'clean_hands', '/dental-saas/images/treatment-room.jpg', 'From £65.00', '45 mins', '', '{\"id\":2,\"slug\":\"dental-hygiene-airflow\",\"title\":\"Dental Hygiene & Airflow Polish\",\"category\":\"Hygiene\",\"badge\":\"Airflow Polish\",\"summary\":\"Gentle calculus removal, plaque decontamination, and high-pressure airflow polishing for brighter smiles.\",\"content\":\"Experience advanced hygiene therapy using Swiss EMS Airflow technology. High-pressure air, warm water, and fine bicarbonate powder gently remove persistent tea, coffee, and tobacco stains without scraping enamel.\\n\\nOur certified dental hygienist also provides tailored interdental cleaning advice and gingival health monitoring.\",\"icon\":\"clean_hands\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £65.00\",\"duration\":\"45 mins\",\"cdt_code\":\"D1110\",\"display_order\":2,\"is_active\":true,\"created_at\":\"2026-11-20 09:15:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 2, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (3, 1, 'composite-white-fillings', 'White Tooth Fillings (Composite)', 'Restorations', 'Composite', 'healing', '/dental-saas/images/surgery-clinic.jpg', 'From £95.00', '45 mins', '', '{\"id\":3,\"slug\":\"composite-white-fillings\",\"title\":\"White Tooth Fillings (Composite)\",\"category\":\"Restorations\",\"badge\":\"Composite\",\"summary\":\"Mercury-free biocompatible tooth-colored composite restorations seamlessly bonded to damaged enamel.\",\"content\":\"Restore broken or decayed teeth with natural, tooth-colored composite resin. Unlike old silver amalgam fillings, modern composite bonds directly to your natural tooth structure, preserving maximum healthy enamel while remaining completely invisible when you smile.\",\"icon\":\"healing\",\"feature_image\":\"/dental-saas/images/surgery-clinic.jpg\",\"starting_price\":\"From £95.00\",\"duration\":\"45 mins\",\"cdt_code\":\"D2391\",\"display_order\":3,\"is_active\":true,\"created_at\":\"2026-11-20 09:30:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 3, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (4, 1, 'root-canal-therapy', 'Root Canal Therapy (Endodontics)', 'Endodontics', 'Pain Relief', 'vital_signs', '/dental-saas/images/treatment-room.jpg', 'From £295.00', '60 mins', '', '{\"id\":4,\"slug\":\"root-canal-therapy\",\"title\":\"Root Canal Therapy (Endodontics)\",\"category\":\"Endodontics\",\"badge\":\"Pain Relief\",\"summary\":\"Precise rotary endodontic treatments eliminating deep pulp infection while saving your natural tooth structure.\",\"content\":\"When dental pulp becomes inflamed or infected due to deep decay or trauma, root canal therapy saves your natural tooth from extraction. Using rotary nickel-titanium instruments and electronic apex locators, our clinicians gently disinfect the canals with local anesthesia for a completely comfortable procedure.\",\"icon\":\"vital_signs\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £295.00\",\"duration\":\"60 mins\",\"cdt_code\":\"D3310\",\"display_order\":4,\"is_active\":true,\"created_at\":\"2026-11-20 09:45:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 4, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (5, 1, 'crowns-and-bridges', 'Dental Crowns & Fixed Bridges', 'Prosthetics', 'Ceramic', 'crown', '/dental-saas/images/hero-patient.jpg', 'From £450.00', '60 mins (2 visits)', '', '{\"id\":5,\"slug\":\"crowns-and-bridges\",\"title\":\"Dental Crowns & Fixed Bridges\",\"category\":\"Prosthetics\",\"badge\":\"Ceramic\",\"summary\":\"High-strength monolithic zirconia and porcelain crowns designed for optimal bite force and natural aesthetics.\",\"content\":\"Custom-engineered dental crowns provide 360-degree protection for weakened or fractured teeth. We utilize high-translucency monolithic zirconia and lithium disilicate (E-Max) ceramics shade-matched precisely to adjacent natural teeth.\",\"icon\":\"crown\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"From £450.00\",\"duration\":\"60 mins (2 visits)\",\"cdt_code\":\"D2740\",\"display_order\":5,\"is_active\":true,\"created_at\":\"2026-11-20 10:00:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 5, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (6, 1, 'invisalign-clear-aligners', 'Invisalign® Clear Aligners', 'Orthodontics', 'Discreet', 'auto_fix_high', '/dental-saas/images/surgery-clinic.jpg', 'From £1,800.00', '4-12 months', '', '{\"id\":6,\"slug\":\"invisalign-clear-aligners\",\"title\":\"Invisalign® Clear Aligners\",\"category\":\"Orthodontics\",\"badge\":\"Discreet\",\"summary\":\"Virtually invisible removable orthodontic aligners gently guiding teeth into alignment without metal brackets.\",\"content\":\"Straighten crowded or crooked teeth with the world\'s most advanced clear aligner system. Custom 3D digital treatment simulations (ClinCheck) let you preview your finished smile before treatment even begins. Aligners are removable for easy eating and brushing.\",\"icon\":\"auto_fix_high\",\"feature_image\":\"/dental-saas/images/surgery-clinic.jpg\",\"starting_price\":\"From £1,800.00\",\"duration\":\"4-12 months\",\"cdt_code\":\"D8090\",\"display_order\":6,\"is_active\":true,\"created_at\":\"2026-11-20 10:15:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 6, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (7, 1, 'tooth-extractions', 'Emergency Tooth Extraction', 'Oral Surgery', 'Same-Day', 'medical_services', '/dental-saas/images/treatment-room.jpg', 'From £120.00', '45 mins', '', '{\"id\":7,\"slug\":\"tooth-extractions\",\"title\":\"Emergency Tooth Extraction\",\"category\":\"Oral Surgery\",\"badge\":\"Same-Day\",\"summary\":\"Atraumatic dental extractions for severely compromised or impacted teeth with local anesthesia numbness.\",\"content\":\"When a tooth cannot be saved through conservative restoration, our experienced dental surgeons perform gentle atraumatic extractions designed to minimize post-operative swelling and preserve bone for future implant replacement.\",\"icon\":\"medical_services\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £120.00\",\"duration\":\"45 mins\",\"cdt_code\":\"D7140\",\"display_order\":7,\"is_active\":true,\"created_at\":\"2026-11-20 10:30:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 7, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);
INSERT INTO `services` (`id`, `clinic_id`, `slug`, `title`, `category`, `badge`, `icon`, `feature_image`, `starting_price`, `duration`, `description`, `details_json`, `display_order`, `is_active`) VALUES (8, 1, 'same-day-emergency-relief', 'Same-Day Emergency Relief', 'Emergency', 'Urgent Care', 'e911_emergency', '/dental-saas/images/hero-patient.jpg', 'Emergency Triage £50.00', '30 mins', '', '{\"id\":8,\"slug\":\"same-day-emergency-relief\",\"title\":\"Same-Day Emergency Relief\",\"category\":\"Emergency\",\"badge\":\"Urgent Care\",\"summary\":\"Dedicated priority slots for severe toothache, abscesses, broken teeth, or sports-related dental trauma.\",\"content\":\"Dental emergencies cannot wait. We reserve dedicated slots each morning and afternoon for urgent cases: severe acute toothache, cracked teeth, lost crowns, or dental facial swelling. Call our triage hotline for prompt same-day pain relief.\",\"icon\":\"e911_emergency\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"Emergency Triage £50.00\",\"duration\":\"30 mins\",\"cdt_code\":\"D0140\",\"display_order\":8,\"is_active\":true,\"created_at\":\"2026-11-20 10:45:00\",\"updated_at\":\"2026-11-24 10:00:00\"}', 8, 1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `details_json`=VALUES(`details_json`);

CREATE TABLE IF NOT EXISTS `patients` (
  `patient_key` VARCHAR(64) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(60) NOT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `dob` VARCHAR(32) DEFAULT NULL,
  `address` TEXT DEFAULT NULL,
  `registration_status` VARCHAR(32) DEFAULT 'new',
  `clinical_notes` TEXT DEFAULT NULL,
  `treatment_records_json` LONGTEXT DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`patient_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
