CREATE TABLE IF NOT EXISTS `invoices` (
  `id` VARCHAR(64) NOT NULL,
  `invoice_no` VARCHAR(64) NOT NULL,
  `patient_key` VARCHAR(64) DEFAULT NULL,
  `patient_name` VARCHAR(255) NOT NULL,
  `patient_phone` VARCHAR(60) NOT NULL,
  `patient_email` VARCHAR(255) DEFAULT NULL,
  `treatment` VARCHAR(255) DEFAULT NULL,
  `total_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `paid_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `payment_method` VARCHAR(60) DEFAULT 'Card',
  `payment_status` VARCHAR(40) DEFAULT 'Paid',
  `invoice_date` DATE DEFAULT NULL,
  `notes` TEXT DEFAULT NULL,
  `items_json` LONGTEXT DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoices_no_unique` (`invoice_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `invoices` (`id`, `invoice_no`, `patient_key`, `patient_name`, `patient_phone`, `patient_email`, `treatment`, `total_amount`, `paid_amount`, `payment_method`, `payment_status`, `invoice_date`, `notes`, `items_json`) VALUES ('inv_seed_1001', 'INV-2026-1001', 'PAT_DEMO_001', 'Sarah Jenkins', '+44 7700 900123', 'sarah.jenkins@example.co.uk', 'Dental Hygiene & Airflow Polish', 65.00, 65.00, 'Card', 'Paid', '2026-11-19', 'Paid at reception desk.', '[{\"description\":\"Dental Hygiene & Airflow Polish (45 mins)\",\"amount\":65}]') ON DUPLICATE KEY UPDATE `payment_status`=VALUES(`payment_status`), `paid_amount`=VALUES(`paid_amount`);
INSERT INTO `invoices` (`id`, `invoice_no`, `patient_key`, `patient_name`, `patient_phone`, `patient_email`, `treatment`, `total_amount`, `paid_amount`, `payment_method`, `payment_status`, `invoice_date`, `notes`, `items_json`) VALUES ('inv_seed_1002', 'INV-2026-1002', 'PAT_DEMO_001', 'Sarah Jenkins', '+44 7700 900123', 'sarah.jenkins@example.co.uk', 'White Tooth Fillings (Composite)', 95.00, 45.00, 'Card', 'Partial', '2026-11-26', 'Deposit £45 paid; £50 remaining.', '[{\"description\":\"White Composite Restoration (UR4)\",\"amount\":95}]') ON DUPLICATE KEY UPDATE `payment_status`=VALUES(`payment_status`), `paid_amount`=VALUES(`paid_amount`);

CREATE TABLE IF NOT EXISTS `appointments` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinic_id` BIGINT UNSIGNED DEFAULT 1,
  `reference` VARCHAR(64) NOT NULL,
  `patient_name` VARCHAR(255) NOT NULL,
  `patient_phone` VARCHAR(60) NOT NULL,
  `patient_email` VARCHAR(255) DEFAULT NULL,
  `patient_status` VARCHAR(40) DEFAULT 'new',
  `doctor_id` INT DEFAULT 1,
  `doctor_name` VARCHAR(255) DEFAULT NULL,
  `treatment` VARCHAR(255) DEFAULT NULL,
  `appointment_date` DATE DEFAULT NULL,
  `appointment_time` VARCHAR(32) DEFAULT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'confirmed',
  `source` VARCHAR(80) DEFAULT 'website',
  `raw_json` LONGTEXT DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `appointments_ref_unique` (`reference`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
