CREATE TABLE IF NOT EXISTS `cms_pages` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `slug` VARCHAR(120) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `route` VARCHAR(255) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'published',
  `is_primary` TINYINT(1) NOT NULL DEFAULT 0,
  `content_json` LONGTEXT DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cms_pages_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `cms_pages` (`slug`, `title`, `route`, `status`, `is_primary`, `content_json`) VALUES ('home', 'Home Page', '/', 'published', 1, '{\"_updated_at\":\"2026-11-25 12:07:29\",\"hero\":{\"eyebrow\":\"NHS & PRIVATE PATIENTS WELCOMED\",\"headline\":\"Make your Dental Experience a\",\"headline_highlight\":\"Lot Brighter\",\"title\":\"Make your Dental Experience a\",\"highlight_word\":\"Lot Brighter\",\"subtitle\":\"Welcome to Acocks Green Dental Practice. Delivering gentle, high-standard dental care for patients of all ages across Birmingham B27. From preventive family appointments to transformative aesthetics, our clinical team puts your comfort first.\",\"cta_primary\":\"Book An Appointment\",\"cta_primary_link\":\"#quick-book\",\"cta_secondary\":\"Emergency Consultation\",\"cta_secondary_link\":\"/contact/#emergency\",\"phone\":\"+44 121 765 2870\",\"emergency_label\":\"Emergency Triage Line\",\"hero_image\":\"/dental-saas/uploads/home/hero-patient.jpg\",\"stats\":[{\"label\":\"Happy Patients\",\"value\":\"5,000+\",\"is_active\":true},{\"label\":\"Dentists & Staff\",\"value\":\"7+\",\"is_active\":true},{\"label\":\"Years of Trust\",\"value\":\"20+\",\"is_active\":true}],\"hero_badges\":[{\"title\":\"CQC Regulated Standards\",\"subtitle\":\"Fully compliant\",\"icon\":\"verified\"},{\"title\":\"Same-Day Emergency Slots\",\"subtitle\":\"Fast pain relief\",\"icon\":\"e911_emergency\"}]},\"services_intro\":{\"eyebrow\":\"Our Practice Services\",\"title\":\"Discover Quality Dental Care in Acocks Green\",\"subtitle\":\"Personalized clinical dental solutions delivered in modern surgeries with low radiation digital radiography and compassionate pacing.\"},\"featured_services\":[{\"id\":1,\"slug\":\"routine-examinations\",\"title\":\"Routine Dental Examinations\",\"category\":\"General Dentistry\",\"badge\":\"Preventive\",\"description\":\"Comprehensive soft tissue, periodontal, and tooth screenings with digital X-rays to preserve oral wellness.\",\"icon\":\"dentistry\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"NHS Band 1 (£26.80) / Private £45.00\",\"duration\":\"30 mins\",\"is_active\":true},{\"id\":2,\"slug\":\"dental-hygiene-airflow\",\"title\":\"Dental Hygiene & Airflow Polish\",\"category\":\"Hygiene\",\"badge\":\"Airflow Polish\",\"description\":\"Gentle calculus removal, plaque decontamination, and high-pressure airflow polishing for brighter smiles.\",\"icon\":\"clean_hands\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £65.00\",\"duration\":\"45 mins\",\"is_active\":true},{\"id\":3,\"slug\":\"composite-white-fillings\",\"title\":\"White Tooth Fillings (Composite)\",\"category\":\"Restorations\",\"badge\":\"Composite\",\"description\":\"Mercury-free biocompatible tooth-colored composite restorations seamlessly bonded to damaged enamel.\",\"icon\":\"healing\",\"feature_image\":\"/dental-saas/images/surgery-clinic.jpg\",\"starting_price\":\"From £95.00\",\"duration\":\"45 mins\",\"is_active\":true},{\"id\":4,\"slug\":\"root-canal-therapy\",\"title\":\"Root Canal Therapy (Endodontics)\",\"category\":\"Endodontics\",\"badge\":\"Pain Relief\",\"description\":\"Precise rotary endodontic treatments eliminating deep pulp infection while saving your natural tooth structure.\",\"icon\":\"vital_signs\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £295.00\",\"duration\":\"60 mins\",\"is_active\":true},{\"id\":5,\"slug\":\"crowns-and-bridges\",\"title\":\"Dental Crowns & Fixed Bridges\",\"category\":\"Prosthetics\",\"badge\":\"Ceramic\",\"description\":\"High-strength monolithic zirconia and porcelain crowns designed for optimal bite force and natural aesthetics.\",\"icon\":\"crown\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"From £450.00\",\"duration\":\"60 mins (2 visits)\",\"is_active\":true},{\"id\":6,\"slug\":\"invisalign-clear-aligners\",\"title\":\"Invisalign® Clear Aligners\",\"category\":\"Orthodontics\",\"badge\":\"Discreet\",\"description\":\"Virtually invisible removable orthodontic aligners gently guiding teeth into alignment without metal brackets.\",\"icon\":\"auto_fix_high\",\"feature_image\":\"/dental-saas/images/surgery-clinic.jpg\",\"starting_price\":\"From £1,800.00\",\"duration\":\"4-12 months\",\"is_active\":true},{\"id\":7,\"slug\":\"tooth-extractions\",\"title\":\"Emergency Tooth Extraction\",\"category\":\"Oral Surgery\",\"badge\":\"Same-Day\",\"description\":\"Atraumatic dental extractions for severely compromised or impacted teeth with local anesthesia numbness.\",\"icon\":\"medical_services\",\"feature_image\":\"/dental-saas/images/treatment-room.jpg\",\"starting_price\":\"From £120.00\",\"duration\":\"45 mins\",\"is_active\":true},{\"id\":8,\"slug\":\"same-day-emergency-relief\",\"title\":\"Same-Day Emergency Relief\",\"category\":\"Emergency\",\"badge\":\"Urgent Care\",\"description\":\"Dedicated priority slots for severe toothache, abscesses, broken teeth, or sports-related dental trauma.\",\"icon\":\"e911_emergency\",\"feature_image\":\"/dental-saas/images/hero-patient.jpg\",\"starting_price\":\"Emergency Triage £50.00\",\"duration\":\"30 mins\",\"is_active\":true}],\"about_summary\":{\"eyebrow\":\"About Acocks Green Practice\",\"title\":\"Dedicated Dental Professionals Serving Birmingham B27\",\"subtitle\":\"Our clinic was established with a clear mission: provide accessible, respectful, and clinically excellent dentistry.\",\"experience_years\":\"20+\",\"patients_served\":\"5,000+\",\"story_paragraphs\":[\"At Acocks Green Dental Practice, we believe that visiting the dentist should be a calm, reassuring experience. Our clinic has been trusted by families across South Birmingham for over two decades.\",\"From children taking their first steps into oral health to adults receiving complex smile restorations, our multi-disciplinary clinicians tailor treatment speeds to your personal comfort level.\"],\"trust_seal\":{\"title\":\"Patient Comfort First\",\"subtitle\":\"Gentle nervous patient protocols\"},\"image_1\":\"/dental-saas/uploads/home/treatment-room.jpg\",\"image_2\":\"/dental-saas/uploads/home/surgery-clinic.jpg\"},\"clinicians\":[{\"id\":1,\"name\":\"Dr. Atandrilla Das\",\"title\":\"BDS Associate Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-das.jpg\",\"bio\":\"Special interest in comprehensive restorative therapy, minimal-prep restorations, and pediatric patient care.\"},{\"id\":2,\"name\":\"Dr. Harjeevan Rai\",\"title\":\"BDS Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-rai.jpg\",\"bio\":\"Focused on preventive oral health, biomechanical restorations, and gentle pain relief treatments.\"},{\"id\":3,\"name\":\"Dr. Nadeem Sohail\",\"title\":\"BDS Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-sohail.jpg\",\"bio\":\"Experienced in complex endodontics, emergency extractions, and crown & bridge oral rehabilitation.\"},{\"id\":4,\"name\":\"Claire\",\"title\":\"Dental Hygienist\",\"badge\":\"Dental Hygienist\",\"avatar\":\"/dental-saas/uploads/home/hygienist-claire.jpg\",\"bio\":\"Leading our hygiene suite with deep periodontal therapy, patient brushing coaching, and airflow stain polishing.\"}],\"support_team\":[{\"name\":\"Hannah\",\"role\":\"Foundation Dentist\"},{\"name\":\"Niamh\",\"role\":\"Foundation Dentist\"},{\"name\":\"Mulaykah Abdurrahman\",\"role\":\"Nurse Apprentice\"},{\"name\":\"Gabriela Popescu\",\"role\":\"Nurse\"},{\"name\":\"Hamza Ahmad\",\"role\":\"Nurse\"},{\"name\":\"Rukhsana Choudhary\",\"role\":\"Nurse\"},{\"name\":\"Richard Gill\",\"role\":\"Nurse\"},{\"name\":\"Jessica William\",\"role\":\"Nurse\"},{\"name\":\"Jade Walker\",\"role\":\"Receptionist\"}],\"testimonials\":{\"average_rating\":4.9,\"total_reviews\":148,\"items\":[{\"name\":\"Sarah Thompson\",\"location\":\"Acocks Green\",\"comment\":\"I have always had dental anxiety, but the team here took the time to explain everything and put me completely at ease. Highly recommended!\",\"treatment\":\"Routine Examination & Hygiene\",\"rating\":5},{\"name\":\"David Miller\",\"location\":\"Solihull\",\"comment\":\"Called in the morning with intense wisdom tooth pain and was accommodated the same day. Extremely professional and pain-free extraction.\",\"treatment\":\"Emergency Dental Care\",\"rating\":5},{\"name\":\"Priya Patel\",\"location\":\"Hall Green\",\"comment\":\"My kids actually look forward to their dental check-ups now! Dr. Das is so gentle and patient with children.\",\"treatment\":\"Family Dental Care\",\"rating\":5}]},\"safety_charter\":{\"title\":\"NHS Sexual Safety Charter Signatory\",\"description\":\"Acocks Green Dental Practice is an official signatory of the NHS Sexual Safety Charter, championing zero tolerance for harassment and fostering a safe, respectful clinical environment.\",\"badge\":\"Official NHS Charter\",\"link_text\":\"Read Our Safety Standards\",\"link_url\":\"https://www.england.nhs.uk/publication/sexual-safety-in-healthcare-charter/\"},\"contact_section\":{\"title\":\"Visit Our Modern Surgery in Birmingham B27\",\"address\":\"1078 Warwick Road, Acocks Green, Birmingham B27 6BH\",\"phone\":\"+44 121 765 2870\",\"email\":\"acocksgreendentalpractice@gmail.com\",\"hours\":[{\"day_range\":\"Monday – Thursday\",\"hours\":\"8:30 AM – 5:30 PM\"},{\"day_range\":\"Friday\",\"hours\":\"8:30 AM – 5:00 PM\"},{\"day_range\":\"Saturday – Sunday\",\"hours\":\"Emergency Triage On-Call\"}],\"map_image\":\"/dental-saas/uploads/home/surgery-clinic.jpg\"},\"seo\":{\"meta_title\":\"Acocks Green Dental Practice | NHS & Private Family Dentist Birmingham B27\",\"meta_description\":\"Trusted NHS & private dental clinic in Acocks Green, Birmingham B27. Routine exams, hygiene, Invisalign, composite fillings, and same-day emergency dental triage.\",\"keywords\":\"dentist Acocks Green, Birmingham B27 dentist, NHS dentist Birmingham, emergency dentist, Invisalign Acocks Green\"},\"sections\":[{\"id\":\"sec_services\",\"type\":\"services_block\",\"category\":\"prebuilt\",\"name\":\"Services Section\",\"page_slug\":\"\",\"eyebrow\":\"Our Practice Services\",\"title\":\"Discover Quality Dental Care in Acocks Green\",\"summary\":\"Personalized clinical dental solutions delivered in modern surgeries with low radiation digital radiography and compassionate pacing.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"View All Treatments\",\"cta_link\":\"/treatments\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":1},{\"id\":\"sec_about\",\"type\":\"page_snippet\",\"category\":\"page_snippet\",\"name\":\"About Our Surgery\",\"page_slug\":\"about-us\",\"eyebrow\":\"About Acocks Green Practice\",\"title\":\"Dedicated Dental Professionals Serving Birmingham B27\",\"summary\":\"Our clinic was established with a clear mission: provide accessible, respectful, and clinically excellent dentistry.\",\"description\":\"At Acocks Green Dental Practice, we believe that visiting the dentist should be a calm, reassuring experience. Our clinic has been trusted by families across South Birmingham for over two decades. From routine checkups to advanced cosmetic aligners, our clinicians pace treatments to your comfort.\",\"layout\":\"thumbnail\",\"feature_image\":\"/dental-saas/uploads/home/surgery-clinic.jpg\",\"image_position\":\"left\",\"column_layout\":\"two_col_split\",\"cta_text\":\"Discover Our Surgery Story\",\"cta_link\":\"/about-us\",\"bg_type\":\"solid\",\"bg_color\":\"#ffffff\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":2},{\"id\":\"sec_team\",\"type\":\"team_block\",\"category\":\"prebuilt\",\"name\":\"Doctors & Dental Surgeons\",\"page_slug\":\"\",\"eyebrow\":\"Clinical Team\",\"title\":\"Dedicated Clinicians & Dental Surgeons\",\"summary\":\"Compassionate care delivered by fully registered dental professionals with decades of combined clinical expertise.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"Meet Full Surgery Team\",\"cta_link\":\"/about-us#team\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":3},{\"id\":\"sec_testimonials\",\"type\":\"testimonials_block\",\"category\":\"prebuilt\",\"name\":\"Patient Testimonials Slider\",\"page_slug\":\"\",\"eyebrow\":\"Patient Feedback\",\"title\":\"What Our Patients Say About Us\",\"summary\":\"Real stories from patients treated at our Acocks Green Birmingham surgery.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"Leave a Google Review\",\"cta_link\":\"https://g.page/review\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":4},{\"id\":\"sec_blog_block_1795604741915\",\"type\":\"blog_block\",\"category\":\"prebuilt\",\"name\":\"Latest Dental & Oral Health Articles\",\"page_slug\":\"\",\"eyebrow\":\"Get the latest news, offers and updates\",\"title\":\"Latest Dental & Oral Health Articles\",\"summary\":\"Clinical insights, preventive brushing advice, and community health updates.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":5},{\"id\":\"sec_charter\",\"type\":\"custom_content\",\"category\":\"custom_content\",\"name\":\"NHS Sexual Safety Charter\",\"page_slug\":\"\",\"eyebrow\":\"Official NHS Charter\",\"title\":\"NHS Sexual Safety Charter Signatory\",\"summary\":\"Acocks Green Dental Practice is an official signatory of the NHS Sexual Safety Charter, championing zero tolerance for harassment and fostering a safe, respectful clinical environment.\",\"description\":\"We are dedicated to safeguarding all staff, patients, and visitors within our clinical facilities.\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"action_bar\",\"cta_text\":\"Read Our Safety Standards\",\"cta_link\":\"https://www.england.nhs.uk/publication/sexual-safety-in-healthcare-charter/\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":6},{\"id\":\"sec_contact\",\"type\":\"contact_block\",\"category\":\"prebuilt\",\"name\":\"Hours & Surgery Location Map\",\"page_slug\":\"\",\"eyebrow\":\"Practice Location\",\"title\":\"Visit Our Modern Surgery in Birmingham B27\",\"summary\":\"Find surgery opening hours, parking information, and telephone reception.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"Call Reception\",\"cta_link\":\"tel:+441217652870\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.3,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":3,\"is_active\":true,\"order\":7}]}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content_json`=VALUES(`content_json`);
INSERT INTO `cms_pages` (`slug`, `title`, `route`, `status`, `is_primary`, `content_json`) VALUES ('about-us', 'About Our Practice & Team', '/about-us', 'published', 0, '{\"_updated_at\":\"2026-11-25 06:59:55\",\"slug\":\"about-us\",\"title\":\"Dedicated to Gentle, High-Quality Family & Cosmetic Dentistry in Acocks Green\",\"hero\":{\"eyebrow\":\"Caring for Birmingham Smiles Since 1998\",\"headline\":\"Dedicated to Gentle, High-Quality Family & Cosmetic Dentistry in Acocks Green\",\"subtitle\":\"With over 25 years of clinical heritage at 1078 Warwick Road, Acocks Green Dental Practice unites compassionate NHS primary dental health with advanced, minimally invasive private and cosmetic care. We believe modern dental visits should feel calm, transparent, and completely unhurried.\",\"image\":\"/dental-saas/uploads/about-us/about-team.jpg\",\"image_caption\":\"Principal Clinicians & Care Team — Warwick Road\",\"cta_primary\":\"Meet Our Team\",\"cta_primary_link\":\"#our-team\",\"cta_secondary\":\"0121 765 2870\",\"cta_secondary_link\":\"tel:+441217652870\",\"trust_badges\":[{\"icon\":\"local_hospital\",\"label\":\"NHS & Private\"},{\"icon\":\"verified_user\",\"label\":\"CQC Regulated\"},{\"icon\":\"workspace_premium\",\"label\":\"BDA Member\"},{\"icon\":\"military_tech\",\"label\":\"Award-Winning\"}]},\"why_us\":{\"eyebrow\":\"Practice Ethos & Clinical Standards\",\"headline\":\"Why Birmingham Patients Choose<br />Acocks Green Dental!\",\"subtitle\":\"We understand that many patients feel anxious or delay treatments due to fear of discomfort or unexpected bills. Our clinicians take time to listen, provide transparent NHS and private guidance, and deliver gentle treatment in a calm, modern setting.\",\"pillars\":[{\"icon\":\"spa\",\"title\":\"Unhurried & Gentle Care\",\"desc\":\"Extra appointment time dedicated to anxious patients, gentle numbing techniques, and comprehensive clinical explanations prior to any procedure.\",\"badge\":\"Dental Phobia Certified\"},{\"icon\":\"biotech\",\"title\":\"Modern Clinical Tech\",\"desc\":\"Low-dose digital 3D radiography, iTero® intraoral digital optical scanners, and painless ultrasonic scaling for fast, accurate treatment planning.\",\"badge\":\"Zero Goop Digital Scans\"},{\"icon\":\"receipt_long\",\"title\":\"Transparent Pathways\",\"desc\":\"Clear upfront cost breakdowns with zero hidden fees, standard NHS bandings, and interest-free 0% APR financing options on qualifying treatments.\",\"badge\":\"0% Finance Options\"},{\"icon\":\"school\",\"title\":\"GDC-Registered Team\",\"desc\":\"Continual postgraduate development, master\'s level restorative clinicians, and dedicated oral hygiene specialists ensuring hospital-grade care.\",\"badge\":\"GDC Regulated Clinicians\"}],\"stats\":[{\"value\":\"25+\",\"label\":\"Years Serving Acocks Green\",\"desc\":\"Continuous community dental trust\"},{\"value\":\"15,000+\",\"label\":\"Smiles Treated\",\"desc\":\"Families, children, and adults\"},{\"value\":\"4.9/5\",\"label\":\"Average Patient Rating\",\"desc\":\"Across Google and NHS Choices\"},{\"value\":\"100%\",\"label\":\"CQC Compliance\",\"desc\":\"Audited safety & sterilization\"}]},\"clinics\":{\"eyebrow\":\"Modern Surgery & Accessible Amenities\",\"headline\":\"State-of-the-Art Surgeries on Warwick Road\",\"subtitle\":\"Designed for comfort, sterility, and seamless clinical efficiency. Located conveniently at 1078 Warwick Road, Birmingham with on-site parking and step-free disabled access.\",\"features\":[{\"icon\":\"radiology\",\"title\":\"Digital X-Ray & Intraoral 3D Imaging Suite\",\"desc\":\"Instant, ultra-low radiation diagnostic imaging displayed chairside on HD screens for transparent patient consultation.\"},{\"icon\":\"sanitizer\",\"title\":\"Dedicated Sterilisation & Decontamination Suite\",\"desc\":\"Fully segregated HTM 01-05 compliant cleanroom utilizing vacuum autoclaves, tracking barcoding, and daily biological spore testing.\"},{\"icon\":\"accessible\",\"title\":\"Step-Free Ground Floor Surgeries\",\"desc\":\"Wheelchair, mobility scooter, and pushchair accessible throughout the clinic, including broad corridors and accessible facilities.\"},{\"icon\":\"chair\",\"title\":\"Comfort-First Patient Lounge\",\"desc\":\"Calming, acoustically treated waiting environment with fresh chilled water, tea/coffee, and high-speed Wi-Fi.\"},{\"icon\":\"directions_bus\",\"title\":\"Free Patient Parking & Transport Links\",\"desc\":\"Dedicated on-site parking at the rear, directly opposite Warwick Road bus stops and 5 minutes from Acocks Green Railway Station.\"}],\"surgery_image\":\"/dental-saas/uploads/about-us/surgery-clinic.jpg\",\"surgery_title\":\"Modern Surgery 1\",\"surgery_desc\":\"Equipped with A-dec 500 ergonomic chair and digital radiographic suite\",\"surgery_badge\":\"Active Clinical Suite\"},\"safety_charter\":{\"eyebrow\":\"Regulatory Rigor & Patient Safeguards\",\"headline\":\"Our NHS Safety Charter & CQC Quality Standards\",\"subtitle\":\"We are deeply committed to delivering safe, dignified, and clinically audited dental care under NHS primary care contracts and private healthcare regulations.\",\"cards\":[{\"icon\":\"verified\",\"title\":\"CQC Regulated & Inspected\",\"desc\":\"Acocks Green Dental Practice is fully registered with the Care Quality Commission and rated compliant in all essential standards of safety, clinical effectiveness, caring, responsiveness, and leadership.\",\"footer_label\":\"Inspection Status: 100% Compliant\"},{\"icon\":\"clean_hands\",\"title\":\"Cross-Infection Control (HTM 01-05)\",\"desc\":\"Gold standard autoclave sterilization, continuous single-use disposables, and daily biological spore testing ensure ultimate reassurance and complete protection for your family.\",\"footer_label\":\"HTM 01-05 Gold Protocol\"},{\"icon\":\"lock\",\"title\":\"Confidentiality & GDPR Compliance\",\"desc\":\"Full compliance with NHS Caldicott Guardian principles, General Dental Council guidelines, and modern 256-bit encrypted digital radiograph and health records archives.\",\"footer_label\":\"Encrypted Health Storage\"}],\"emergency_box\":{\"title\":\"Emergency & Out-of-Hours Dental Support\",\"subtitle\":\"Experiencing severe dental pain, bleeding, or facial trauma outside regular practice hours?\",\"phone\":\"+44 121 765 2870\",\"nhs111\":\"111\"}},\"seo\":{\"meta_title\":\"About Our Practice & Clinical Team | Acocks Green Dental Practice\",\"meta_description\":\"Discover our patient-first clinical philosophy, hospital-grade sterilization protocols, and multi-specialty dental expertise in Birmingham B27.\",\"keywords\":\"dental clinic about us, dental philosophy, sterile dental facility, multi-specialty dentistry, Acocks Green dentist\"},\"sections\":[{\"id\":\"sec_about_why_us\",\"type\":\"why_us_block\",\"category\":\"prebuilt\",\"name\":\"Why Us & Ethos Pillars\",\"page_slug\":\"\",\"eyebrow\":\"Practice Ethos & Clinical Standards\",\"title\":\"Why Birmingham Patients Choose<br />Acocks Green Dental!\",\"summary\":\"We understand that many patients feel anxious or delay treatments due to fear of discomfort or unexpected bills. Our clinicians take time to listen, provide transparent NHS and private guidance, and deliver gentle treatment in a calm, modern setting.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"is_active\":true,\"order\":1},{\"id\":\"sec_about_team\",\"type\":\"team_block\",\"category\":\"prebuilt\",\"name\":\"Our Clinical Team\",\"page_slug\":\"\",\"eyebrow\":\"Meet Our Experienced Clinicians\",\"title\":\"GDC-Registered Dentists, Hygienists & Dental Nurses\",\"summary\":\"Every clinician at Acocks Green Dental Practice shares a commitment to gentle clinical precision, continuous professional learning, and friendly patient care.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"is_active\":true,\"order\":2},{\"id\":\"sec_about_clinics\",\"type\":\"clinics_block\",\"category\":\"prebuilt\",\"name\":\"Our Clinics & Amenities\",\"page_slug\":\"\",\"eyebrow\":\"Modern Surgery & Accessible Amenities\",\"title\":\"State-of-the-Art Surgeries on Warwick Road\",\"summary\":\"Designed for comfort, sterility, and seamless clinical efficiency. Located conveniently at 1078 Warwick Road, Birmingham with on-site parking and step-free disabled access.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"is_active\":true,\"order\":3},{\"id\":\"sec_about_charter\",\"type\":\"safety_charter_cards\",\"category\":\"prebuilt\",\"name\":\"NHS Safety Charter & CQC Standards\",\"page_slug\":\"\",\"eyebrow\":\"Regulatory Rigor & Patient Safeguards\",\"title\":\"Our NHS Safety Charter & CQC Quality Standards\",\"summary\":\"We are deeply committed to delivering safe, dignified, and clinically audited dental care under NHS primary care contracts and private healthcare regulations.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"is_active\":true,\"order\":4},{\"id\":\"sec_about_reviews\",\"type\":\"testimonials_block\",\"category\":\"prebuilt\",\"name\":\"Patient Reviews & Stories\",\"page_slug\":\"\",\"eyebrow\":\"Patient Voices\",\"title\":\"What Our Patients Say About Us\",\"summary\":\"Verified reviews from patients cared for at our Acocks Green dental practice.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#f0fdf4\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"is_active\":true,\"order\":5}],\"clinicians\":[{\"id\":1,\"name\":\"Dr. Atandrilla Das\",\"title\":\"BDS Associate Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-das.jpg\",\"bio\":\"Special interest in comprehensive restorative therapy, minimal-prep restorations, and pediatric patient care.\"},{\"id\":2,\"name\":\"Dr. Harjeevan Rai\",\"title\":\"BDS Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-rai.jpg\",\"bio\":\"Focused on preventive oral health, biomechanical restorations, and gentle pain relief treatments.\"},{\"id\":3,\"name\":\"Dr. Nadeem Sohail\",\"title\":\"BDS Dental Surgeon\",\"badge\":\"Associate Dentist\",\"avatar\":\"/dental-saas/uploads/home/doctor-sohail.jpg\",\"bio\":\"Experienced in complex endodontics, emergency extractions, and crown & bridge oral rehabilitation.\"},{\"id\":4,\"name\":\"Claire\",\"title\":\"Dental Hygienist\",\"badge\":\"Dental Hygienist\",\"avatar\":\"/dental-saas/uploads/home/hygienist-claire.jpg\",\"bio\":\"Leading our hygiene suite with deep periodontal therapy, patient brushing coaching, and airflow stain polishing.\"}]}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content_json`=VALUES(`content_json`);
INSERT INTO `cms_pages` (`slug`, `title`, `route`, `status`, `is_primary`, `content_json`) VALUES ('blog', 'Dental Health Blog & News', '/blog', 'published', 0, '{\"_updated_at\":\"2026-11-25 12:29:02\",\"slug\":\"blog\",\"template\":\"blog_list\",\"title\":\"Dental Health Blog & News\",\"hero\":{\"eyebrow\":\"Clinical Insights & Oral Wellness\",\"headline\":\"Dental Health Blog & Patient Guides\",\"subtitle\":\"Evidence-based dental advice, NHS & private care tips, and practice updates from our Birmingham B27 clinical team.\",\"image\":\"/dental-saas/uploads/home/surgery-clinic.jpg\",\"cta_primary\":\"Book An Appointment\",\"cta_primary_link\":\"#quick-book\"},\"sections\":[{\"id\":\"sec_blog_intro\",\"type\":\"blog_block\",\"category\":\"prebuilt\",\"name\":\"All Blog Posts Grid\",\"page_slug\":\"\",\"eyebrow\":\"Latest Articles\",\"title\":\"Recent Dental Health Articles\",\"summary\":\"Written and clinically reviewed by our GDC-registered dental surgeons.\",\"description\":\"\",\"layout\":\"thumbnail\",\"feature_image\":\"\",\"image_position\":\"right\",\"column_layout\":\"two_col_split\",\"cta_text\":\"\",\"cta_link\":\"\",\"bg_type\":\"default\",\"bg_color\":\"#ffffff\",\"bg_gradient_start\":\"#094713\",\"bg_gradient_end\":\"#15803d\",\"bg_gradient_angle\":\"135deg\",\"bg_image\":\"\",\"bg_overlay_color\":\"#000000\",\"bg_overlay_opacity\":0.6,\"text_contrast\":\"auto\",\"padding_y\":\"normal\",\"grid_cols\":4,\"is_active\":true,\"order\":1}],\"blog_posts\":[{\"id\":\"post_1\",\"title\":\"How Often Should You Book a Dental Hygiene & Airflow Polish?\",\"category\":\"Preventive Care\",\"date\":\"2026-11-18\",\"author\":\"Claire, Dental Hygienist\",\"read_time\":\"4 min read\",\"image\":\"/dental-saas/uploads/home/treatment-room.jpg\",\"excerpt\":\"Learn how Airflow warm-water polishing removes stubborn tea, coffee, and plaque biofilm gently without scraping sensitive enamel.\",\"content\":\"Regular dental hygiene appointments every 3 to 6 months are essential for preventing gum disease and preserving natural enamel. Our Airflow system uses a gentle stream of warm water, air, and fine erythritol powder to lift surface stains painlessly.\"},{\"id\":\"post_2\",\"title\":\"NHS vs Private Dental Care in Birmingham: What Is Included?\",\"category\":\"Patient Guides\",\"date\":\"2026-11-10\",\"author\":\"Dr. Atandrilla Das\",\"read_time\":\"4 min read\",\"image\":\"/dental-saas/uploads/home/hero-patient.jpg\",\"excerpt\":\"A transparent breakdown of NHS Band 1, Band 2, and Band 3 treatments alongside private cosmetic options like white fillings and Invisalign.\",\"content\":\"Understanding your dental treatment options should always be clear and stress-free. At Acocks Green Dental Practice, we explain both NHS and private pathways upfront so you can choose what suits your clinical needs and budget.\"},{\"id\":\"post_3\",\"title\":\"Same-Day Emergency Dental Triage: What Counts as Urgent?\",\"category\":\"Emergency Care\",\"date\":\"2026-11-02\",\"author\":\"Dr. Nadeem Sohail\",\"read_time\":\"4 min read\",\"image\":\"/dental-saas/uploads/home/surgery-clinic.jpg\",\"excerpt\":\"Severe toothache, facial swelling, or a knocked-out tooth? Here is how our Birmingham B27 triage line gets you seen the very same day.\",\"content\":\"Dental emergencies can happen without warning. If you experience severe throbbing pain, swelling, or dental trauma, call our reception on +44 121 765 2870 before 10:00 AM for priority same-day clinical triage.\"}],\"seo\":{\"meta_title\":\"Dental Health Blog & News | Acocks Green Dental Practice\",\"meta_description\":\"Acocks Green Dental Practice — NHS & Private Family Dentistry in Birmingham B27.\",\"keywords\":\"dental clinic Birmingham, Acocks Green dentist, dental blog\"}}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content_json`=VALUES(`content_json`);
