CREATE TABLE IF NOT EXISTS `cms_settings` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `setting_key` VARCHAR(120) NOT NULL,
  `setting_value` LONGTEXT DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cms_settings_key_unique` (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `cms_settings` (`setting_key`, `setting_value`) VALUES ('theme_and_branding', '{\"theme_name\":\"acocks-green\",\"display_name\":\"Acocks Green Dental Practice\",\"colors\":{\"primary\":\"#0d631b\",\"primary_hover\":\"#0a4f15\",\"secondary\":\"#45664e\",\"surface\":\"#f2fcf5\",\"surface_muted\":\"#ecf6ef\",\"text_primary\":\"#151d1a\",\"text_secondary\":\"#40493d\",\"nhs_blue\":\"#005eb8\",\"status_error\":\"#ba1a1a\",\"brand_accent_glow\":\"#E8F5E9\"},\"typography\":{\"font_family\":\"Plus Jakarta Sans\",\"heading_font\":\"Plus Jakarta Sans\",\"body_font\":\"Work Sans\"},\"branding\":{\"clinic_name\":\"Acocks Green Dental Clinic\",\"tagline\":\"Modern Family Dentistry\",\"logo_url\":\"/dental-saas/images/acocks-green-logo.png\",\"email\":\"reception@acocksgreendental.co.uk\",\"form_email\":\"bookings@acocksgreendental.co.uk\",\"contact_forward_emails\":\"bookings@acocksgreendental.co.uk, reception@acocksgreendental.co.uk\",\"phone\":\"+919904379260\",\"whatsapp\":\"+919904379260\",\"emergency_phone\":\"+919904379260\",\"address\":\"1078 Warwick Road, Acocks Green, Birmingham B27 6BH\",\"cqc_status\":\"CQC Regulated Standards\",\"nhs_registered\":true},\"system_settings\":{\"session_timeout_hours\":10,\"log_retention_months\":2,\"default_slot_duration\":30,\"require_2fa\":true,\"maintenance_mode\":false},\"header_menu\":[{\"title\":\"Home\",\"path\":\"/\"},{\"title\":\"Treatments & Services\",\"path\":\"/treatments\"},{\"title\":\"About Us\",\"path\":\"/about-us\"},{\"title\":\"Patient Safety & Charter\",\"path\":\"/safety-charter\"},{\"title\":\"Contact & Location\",\"path\":\"/contact\"}],\"footer_data\":{\"quick_links\":[{\"title\":\"Home\",\"path\":\"/\"},{\"title\":\"Meet Our Clinicians\",\"path\":\"/#team\"},{\"title\":\"Emergency Dentistry\",\"path\":\"/treatments\"},{\"title\":\"NHS Patient Registration\",\"path\":\"/contact\"},{\"title\":\"Contact Us\",\"path\":\"/contact\"}],\"services_links\":[{\"title\":\"Routine Dental Examinations\",\"path\