CREATE TABLE IF NOT EXISTS `blog_posts` (
  `id` VARCHAR(64) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(191) NOT NULL,
  `status` VARCHAR(32) NOT NULL DEFAULT 'published',
  `published_at` VARCHAR(40) DEFAULT NULL,
  `author` VARCHAR(191) DEFAULT NULL,
  `featured_image` VARCHAR(500) DEFAULT NULL,
  `featured_image_alt` VARCHAR(255) DEFAULT NULL,
  `excerpt` TEXT DEFAULT NULL,
  `content` LONGTEXT DEFAULT NULL,
  `meta_json` LONGTEXT DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `blog_posts_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `status`, `published_at`, `author`, `featured_image`, `featured_image_alt`, `excerpt`, `content`, `meta_json`) VALUES ('post_1', 'How Often Should You Book a Dental Hygiene & Airflow Polish?', 'how-often-dental-hygiene-airflow', 'published', '2026-11-18T09:00', 'Claire, Dental Hygienist', '/uploads/home/treatment-room.jpg', 'Dental hygienist performing Airflow polish in Birmingham clinic', 'Learn how Airflow warm-water polishing removes stubborn tea, coffee, and plaque biofilm gently without scraping sensitive enamel.', '<p>Regular dental hygiene appointments every <strong>3 to 6 months</strong> are essential for preventing gum disease, halitosis, and preserving natural enamel.</p><h2>Why Airflow Warm-Water Polishing?</h2><p>Unlike traditional abrasive scaling pastes, our Swiss-engineered Airflow system uses a gentle stream of warm water, air, and fine erythritol powder to lift surface stains and bacterial biofilm painlessly—even around dental implants, veneers, and sensitive root surfaces.</p><ul><li><strong>Zero scraping sensitivity:</strong> Warm water reduces thermal shock for sensitive teeth.</li><li><strong>Deep stain removal:</strong> Clears tea, coffee, red wine, and smoking stains in one visit.</li><li><strong>Gum health protection:</strong> Disrupts sub-gingival plaque biofilm safely.</li></ul>', '{\"category_ids\":[\"cat_preventive\"],\"tag_ids\":[\"tag_airflow\",\"tag_hygiene\",\"tag_birmingham\"],\"faqs\":[{\"question\":\"Does Airflow polishing hurt sensitive teeth?\",\"answer\":\"No. Because Airflow uses body-temperature warm water and ultra-fine erythritol powder rather than metal scraping alone, most patients find it remarkably comfortable.\",\"is_active\":true},{\"question\":\"How long does an Airflow hygiene appointment take?\",\"answer\":\"A standard hygiene & Airflow session lasts 30 to 45 minutes depending on plaque and stain build-up.\",\"is_active\":true}],\"seo\":{\"meta_title\":\"How Often Should You Book Dental Hygiene & Airflow Polish? | Acocks Green Dental\",\"meta_description\":\"Discover how often to book dental hygiene appointments and why Airflow warm-water polishing is ideal for sensitive teeth in Birmingham B27.\",\"meta_keywords\":\"dental hygiene birmingham, airflow polish, plaque removal, acocks green dentist\",\"og_image\":\"\",\"no_index\":false}}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`);
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `status`, `published_at`, `author`, `featured_image`, `featured_image_alt`, `excerpt`, `content`, `meta_json`) VALUES ('post_2', 'NHS vs Private Dental Care in Birmingham: What Is Included?', 'nhs-vs-private-dental-care-birmingham', 'published', '2026-11-10T10:30', 'Dr. Atandrilla Das', '/uploads/home/hero-patient.jpg', 'Dentist explaining NHS and private treatment options to a smiling patient', 'A transparent breakdown of NHS Band 1, Band 2, and Band 3 treatments alongside private cosmetic options like white fillings and Invisalign.', '<p>Understanding your dental treatment options should always be clear and stress-free. At Acocks Green Dental Practice, we explain both <strong>NHS and private pathways</strong> upfront so you can choose what suits your clinical needs and budget.</p><h2>NHS Dental Charge Bands Explained</h2><ul><li><strong>Band 1 (£26.80):</strong> Clinical examination, diagnosis, X-rays, and preventive oral health advice.</li><li><strong>Band 2 (£73.50):</strong> Everything in Band 1 plus fillings, root canal treatment, and extractions.</li><li><strong>Band 3 (£319.10):</strong> Complex laboratory work including crowns, bridges, and dentures.</li></ul><h2>When Patients Choose Private Care</h2><p>Private options allow longer unhurried appointments, tooth-coloured composite fillings on back molars, Airflow stain polishing, and discreet Invisalign aligner orthodontics.</p>', '{\"category_ids\":[\"cat_guides\"],\"tag_ids\":[\"tag_nhs\",\"tag_private\",\"tag_birmingham\"],\"faqs\":[{\"question\":\"Can I mix NHS and private dental treatments?\",\"answer\":\"Yes. Many patients have their routine NHS check-up and choose private cosmetic upgrades such as white composite fillings or teeth whitening.\",\"is_active\":true}],\"seo\":{\"meta_title\":\"NHS vs Private Dental Care in Birmingham B27 | Patient Guide\",\"meta_description\":\"Compare NHS Dental Bands 1, 2, and 3 with private dental treatments at Acocks Green Dental Practice in Birmingham.\",\"meta_keywords\":\"nhs dentist birmingham, nhs dental bands, private dentist acocks green\",\"og_image\":\"\",\"no_index\":false}}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`);
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `status`, `published_at`, `author`, `featured_image`, `featured_image_alt`, `excerpt`, `content`, `meta_json`) VALUES ('post_3', 'Same-Day Emergency Dental Triage: What Counts as Urgent?', 'same-day-emergency-dental-triage', 'published', '2026-11-02T08:30', 'Dr. Nadeem Sohail', '/uploads/home/surgery-clinic.jpg', 'Modern emergency dental treatment suite at Acocks Green Dental', 'Severe toothache, facial swelling, or a knocked-out tooth? Here is how our Birmingham B27 triage line gets you seen the very same day.', '<p>Dental emergencies can happen without warning. If you experience severe throbbing pain, facial swelling, or dental trauma, call our reception on <strong>+44 121 765 2870</strong> before 10:00 AM for priority same-day clinical triage.</p><h2>Symptoms Requiring Urgent Same-Day Care</h2><ul><li>Uncontrolled toothache disrupting sleep despite painkillers</li><li>Facial or gum swelling, abscess, or fever</li><li>Knocked-out, loosened, or fractured adult tooth</li><li>Lost crown or filling causing acute nerve sensitivity</li></ul>', '{\"category_ids\":[\"cat_emergency\"],\"tag_ids\":[\"tag_emergency\",\"tag_birmingham\"],\"faqs\":[{\"question\":\"Do I need to be a registered patient for emergency triage?\",\"answer\":\"No. We reserve daily emergency triage slots for both registered and unregistered patients in Birmingham B27.\",\"is_active\":true}],\"seo\":{\"meta_title\":\"Same-Day Emergency Dentist Birmingham B27 | Urgent Triage\",\"meta_description\":\"Need an emergency dentist in Acocks Green, Birmingham? Learn what counts as urgent and how to book same-day triage.\",\"meta_keywords\":\"emergency dentist birmingham, same day dental triage, toothache relief b27\",\"og_image\":\"\",\"no_index\":false}}') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`);

CREATE TABLE IF NOT EXISTS `contact_submissions` (
  `id` VARCHAR(64) NOT NULL,
  `reference` VARCHAR(64) NOT NULL,
  `patient_status` VARCHAR(40) DEFAULT 'new',
  `full_name` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(60) NOT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `service_required` VARCHAR(255) DEFAULT NULL,
  `message` TEXT DEFAULT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'new',
  `raw_json` LONGTEXT DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `assistant_chat_logs` (
  `session_id` VARCHAR(80) NOT NULL,
  `visitor_name` VARCHAR(255) DEFAULT NULL,
  `phone` VARCHAR(60) DEFAULT NULL,
  `service_interest` VARCHAR(255) DEFAULT NULL,
  `booking_reference` VARCHAR(64) DEFAULT NULL,
  `messages_json` LONGTEXT DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `activity_logs` (
  `id` VARCHAR(64) NOT NULL,
  `user_key` VARCHAR(64) NOT NULL,
  `user_name` VARCHAR(255) DEFAULT NULL,
  `role_key` VARCHAR(60) DEFAULT NULL,
  `module` VARCHAR(100) DEFAULT NULL,
  `action` VARCHAR(255) DEFAULT NULL,
  `status` VARCHAR(32) DEFAULT 'Success',
  `details_json` LONGTEXT DEFAULT NULL,
  `ip` VARCHAR(64) DEFAULT NULL,
  `created_at` VARCHAR(40) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

